<template><view class="app-page onboarding"><ui-header title=""/><view v-if="step===1" class="step"><text class="title">选择性别</text><text class="subtitle">用于为你推荐更合适的陪玩服务</text><view class="choices"><view :class="['choice','boy',{active:gender==='男'}]" @tap="gender='男'"><view class="choice-icon"><ui-icon name="male" :size="62"/></view><text>男生</text></view><view :class="['choice','girl',{active:gender==='女'}]" @tap="gender='女'"><view class="choice-icon"><ui-icon name="female" :size="62"/></view><text>女生</text></view></view><view :class="['next',{disabled:!gender}]" @tap="nextStep">下一步</view></view><view v-else class="step"><text class="title">选择性格</text><text class="subtitle">让匹配和交流更符合你的偏好</text><view class="personality"><view :class="['person-card','introvert',{active:personality==='i'}]" @tap="personality='i'"><ui-icon name="message-circle" :size="62" tone="white"/><text>慢热安静</text></view><view :class="['person-card','extrovert',{active:personality==='e'}]" @tap="personality='e'"><ui-icon name="users" :size="62" tone="white"/><text>热情开朗</text></view></view><view :class="['next',{disabled:!personality}]" @tap="finish">确定</view></view></view></template>
<script>export default{data(){return{step:1,gender:'',personality:'',next:'/pages/profile/index'}},onLoad(q){if(q.next)this.next=decodeURIComponent(q.next)},methods:{nextStep(){if(this.gender)this.step=2},finish(){if(!this.personality)return;uni.setStorageSync('preferences',{gender:this.gender,personality:this.personality});uni.reLaunch({url:this.next})}}}</script>
<style scoped>.onboarding{padding-bottom:0;background:linear-gradient(180deg,#f8faff,#fff)}.step{padding:88rpx 50rpx;display:flex;flex-direction:column;align-items:center}.title{font-size:42rpx;font-weight:900}.subtitle{margin-top:18rpx;color:var(--muted);font-size:24rpx}.choices{display:flex;gap:70rpx;margin-top:150rpx}.choice{display:flex;flex-direction:column;align-items:center;gap:20rpx;color:var(--text);font-size:30rpx;font-weight:700}.choice-icon{width:126rpx;height:126rpx;display:flex;align-items:center;justify-content:center;border-radius:50%;background:#eef3ff}.girl .choice-icon{background:#fff0f5}.choice.active .choice-icon{box-shadow:0 0 0 10rpx rgba(85,110,230,.14)}.next{width:100%;height:88rpx;margin-top:210rpx;display:flex;align-items:center;justify-content:center;border-radius:44rpx;background:var(--primary);color:#fff;box-shadow:var(--shadow-button)}.next.disabled{opacity:.4;box-shadow:none}.personality{display:flex;gap:30rpx;margin-top:130rpx}.person-card{width:250rpx;height:250rpx;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:24rpx;border-radius:30rpx;color:#fff;font-size:28rpx;font-weight:800}.introvert{background:linear-gradient(145deg,#6d83e9,#455cc8)}.extrovert{background:linear-gradient(145deg,#ff769b,#ef416a)}.person-card.active{box-shadow:0 0 0 10rpx rgba(85,110,230,.14)}</style>
